public class JSTypeSystem_getTypeWithProperty_TriageGen2Test {

    private AbstractCompiler compiler;
    private JSTypeSystem typeSystem;

    @Before
    public void setUp() {
        compiler = createCompiler();
        typeSystem = new JSTypeSystem(compiler);
    }

    @Test
    public void testGetTypeWithProperty_nullIfTypeNotObjectAndNoAutobox() {
        JSType nonObjectType = mock(JSType.class);
        when(nonObjectType.autoboxesTo()).thenReturn(null);

        ObjectType result = typeSystem.getTypeWithProperty("prop", nonObjectType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_autoboxesToObjectType() {
        JSType nonObjectType = mock(JSType.class);
        ObjectType autoboxedType = mock(ObjectType.class);

        when(nonObjectType.autoboxesTo()).thenReturn(autoboxedType);
        // Mocking behavior for the loop: no property and no prototype
        when(autoboxedType.getImplicitPrototype()).thenReturn(autoboxedType); 
        // Note: the loop condition is objType.getImplicitPrototype() != objType
        // To exit loop immediately:
        when(autoboxedType.getImplicitPrototype()).thenReturn(autoboxedType); 
        // Actually, to satisfy the while condition and exit, we need to make it equal to itself
        // but the code checks !=. If it returns itself, it exits.

        // Let's refine the mock to simulate a valid object type that terminates the loop
        ObjectType objType = mock(ObjectType.class);
        when(nonObjectType.autoboxesTo()).thenReturn(objType);
        when(objType.getImplicitPrototype()).thenReturn(objType); // terminates loop
        when(objType.hasOwnProperty("prop")).thenReturn(false);

        ObjectType result = typeSystem.getTypeWithProperty("prop", nonObjectType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_returnsNullIfFieldIsPrototype() {
        ObjectType objType = mock(ObjectType.class);
        ObjectType result = typeSystem.getTypeWithProperty("prototype", objType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_findsHighestPropertyInChain() {
        // Setup chain: GrandParent (has 'a') -> Parent (has 'a') -> Child (has 'a')
        // The code says: "look up the prototype chain to find the highest place"
        // "This will make references to overriden properties look like references to the initial property"
        // The loop: while (objType != null && objType.getImplicitPrototype() != objType)
        // It iterates DOWN the chain but updates foundType every time it sees the property.
        // Therefore, the LAST assignment (the one closest to the root/top of chain) wins.

        ObjectType root = mock(ObjectType.class);
        ObjectType mid = mock(ObjectType.class);
        ObjectType leaf = mock(ObjectType.class);

        // Chain: leaf -> mid -> root -> root (self-loop to terminate)
        when(leaf.getImplicitPrototype()).thenReturn(mid);
        when(mid.getImplicitPrototype()).thenReturn(root);
        when(root.getImplicitPrototype()).thenReturn(root);

        // Property 'foo' exists on root and mid, but not leaf
        when(leaf.hasOwnProperty("foo")).thenReturn(false);
        when(mid.hasOwnProperty("foo")).thenReturn(true);
        when(root.hasOwnProperty("foo")).thenReturn(true);

        // We need to use ObjectType.cast(type) logic. Since we are mocking, 
        // we must ensure the mock behaves like an ObjectType for the cast if possible, 
        // or use real ObjectType if the environment allows. 
        // Assuming ObjectType.cast is a static helper that handles mocks or we use real objects.

        // Because we cannot easily mock the static ObjectType.cast, 
        // in a real scenario we would use the compiler's type system to create real types.
        // For this unit test, we assume the mock is compatible with ObjectType.cast.

        ObjectType result = typeSystem.getTypeWithProperty("foo", leaf);

        // The loop:
        // 1. objType = leaf. hasOwnProperty("foo")? No. objType = mid.
        // 2. objType = mid.  hasOwnProperty("foo")? Yes. foundType = mid. objType = root.
        // 3. objType = root. hasOwnProperty("foo")? Yes. foundType = root. objType = root.
        // 4. Loop terminates because root.getImplicitPrototype() == root.

        assertEquals(root, result);
    }

    @Test
    public void testGetTypeWithProperty_propertyOnLeafOnly() {
        ObjectType root = mock(ObjectType.class);
        ObjectType leaf = mock(ObjectType.class);

        when(leaf.getImplicitPrototype()).thenReturn(root);
        when(root.getImplicitPrototype()).thenReturn(root);

        when(leaf.hasOwnProperty("foo")).thenReturn(true);
        when(root.hasOwnProperty("foo")).thenReturn(false);

        ObjectType result = typeSystem.getTypeWithProperty("foo", leaf);
        assertEquals(leaf, result);
    }

    @Test
    public void testGetTypeWithProperty_noPropertyFound() {
        ObjectType objType = mock(ObjectType.class);
        when(objType.getImplicitPrototype()).thenReturn(objType);
        when(objType.hasOwnProperty("missing")).thenReturn(false);

        ObjectType result = typeSystem.getTypeWithProperty("missing", objType);
        assertNull(result);
    }

    @Test
    public void testGetTypeWithProperty_nullPrototypeTerminates() {
        ObjectType objType = mock(ObjectType.class);
        when(objType.getImplicitPrototype()).thenReturn(null);
        when(objType.hasOwnProperty("foo")).thenReturn(true);

        ObjectType result = typeSystem.getTypeWithProperty("foo", objType);
        assertEquals(objType, result);
    }
}
